// Secure application with proper environment variable usage
// Load environment variables first
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const winston = require('winston');

// ============================================
// Configuration Validation
// ============================================

const validateConfig = () => {
  const requiredVars = ['NODE_ENV'];
  const missingVars = requiredVars.filter(v => !process.env[v]);

  if (missingVars.length > 0) {
    throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
  }

  // Validate PORT is a valid port number
  const port = parseInt(process.env.PORT || '3000', 10);
  if (isNaN(port) || port < 1 || port > 65535) {
    throw new Error(`Invalid PORT: must be between 1 and 65535, got ${process.env.PORT}`);
  }

  return {
    port,
    host: process.env.HOST || 'localhost',
    nodeEnv: process.env.NODE_ENV || 'development',
    appName: process.env.APP_NAME || 'secure-app',
    version: process.env.VERSION || '1.0.0',
    logLevel: process.env.LOG_LEVEL || 'info',
    corsOrigin: process.env.CORS_ORIGIN || 'http://localhost:3000',
    corsCredentials: process.env.CORS_CREDENTIALS === 'true',
    rateLimitWindow: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10),
    rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX || '100', 10),
    mockUsers: JSON.parse(process.env.MOCK_USERS || '[]')
  };
};

let config;
try {
  config = validateConfig();
} catch (error) {
  console.error('Configuration error:', error.message);
  process.exit(1);
}

// ============================================
// Logger Setup
// ============================================

const logger = winston.createLogger({
  level: config.logLevel,
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: config.appName },
  transports: [
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.printf(({ timestamp, level, message, service }) => {
          return `${timestamp} [${service}] ${level}: ${message}`;
        })
      )
    })
  ]
});

// ============================================
// Express App Setup
// ============================================

const app = express();

// Middleware: Security Headers
app.use(helmet());

// Middleware: CORS
app.use(cors({
  origin: config.corsOrigin.split(',').map(o => o.trim()),
  credentials: config.corsCredentials,
  maxAge: 3600,
  methods: ['GET', 'POST', 'PUT', 'DELETE']
}));

// Middleware: Rate Limiting
const limiter = rateLimit({
  windowMs: config.rateLimitWindow,
  max: config.rateLimitMax,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({
      error: 'Too many requests',
      retryAfter: req.rateLimit.resetTime
    });
  }
});

app.use(limiter);

// Middleware: Request Logging
app.use((req, res, next) => {
  logger.debug(`${req.method} ${req.path}`, {
    ip: req.ip,
    userAgent: req.get('user-agent')
  });
  next();
});

// ============================================
// Routes
// ============================================

/**
 * Health Check Endpoint
 * Returns application status and metadata
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      service: config.appName,
      version: config.version,
      environment: config.nodeEnv,
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    logger.error('Health check error', { error: error.message });
    res.status(500).json({ error: 'Health check failed' });
  }
});

/**
 * Users Endpoint
 * Returns list of users (currently from mock data)
 * In production, this would fetch from a database
 */
app.get('/users', (req, res) => {
  try {
    // Use mock data from environment or return empty array
    const users = config.mockUsers || [];

    logger.info(`Fetched ${users.length} users`);
    res.status(200).json(users);
  } catch (error) {
    logger.error('Users endpoint error', { error: error.message });
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});

/**
 * Configuration Info Endpoint (Development Only)
 * Returns current configuration (without sensitive data)
 */
if (config.nodeEnv === 'development') {
  app.get('/config', (req, res) => {
    res.json({
      port: config.port,
      host: config.host,
      nodeEnv: config.nodeEnv,
      appName: config.appName,
      version: config.version,
      logLevel: config.logLevel,
      corsOrigin: config.corsOrigin,
      rateLimitWindow: config.rateLimitWindow,
      rateLimitMax: config.rateLimitMax
    });
  });
}

// ============================================
// Error Handling
// ============================================

// 404 Not Found
app.use((req, res) => {
  logger.warn(`404 Not Found: ${req.method} ${req.path}`);
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });
});

// Global Error Handler
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method
  });

  const statusCode = err.statusCode || 500;
  const response = {
    error: 'Internal server error',
    timestamp: new Date().toISOString()
  };

  // Include error details in development only
  if (config.nodeEnv === 'development') {
    response.details = err.message;
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================
// Server Startup
// ============================================

let server;

const startServer = () => {
  server = app.listen(config.port, config.host, () => {
    logger.info(
      `[${config.appName}] Server started successfully`,
      {
        url: `http://${config.host}:${config.port}`,
        environment: config.nodeEnv,
        version: config.version
      }
    );
  });

  server.on('error', (err) => {
    if (err.code === 'EADDRINUSE') {
      logger.error(`Port ${config.port} is already in use`);
    } else {
      logger.error('Server error', { error: err.message });
    }
    process.exit(1);
  });
};

// Start server only if not imported as module
if (require.main === module) {
  startServer();
}

// ============================================
// Graceful Shutdown
// ============================================

const gracefulShutdown = (signal) => {
  logger.info(`Received ${signal}, starting graceful shutdown...`);

  if (server) {
    server.close(() => {
      logger.info('HTTP server closed');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      logger.error('Forcing shutdown due to timeout');
      process.exit(1);
    }, 10000);
  } else {
    process.exit(0);
  }
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('Uncaught exception', {
    message: err.message,
    stack: err.stack
  });
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled rejection', {
    reason: reason,
    promise: promise
  });
  process.exit(1);
});

module.exports = app;

