  console.log('Server running on port 3000');
});
```

**Issues:**
- Hardcoded to port 3000
- Cannot be changed without modifying source code
- Different environments may need different ports
- Production systems may conflict on port 3000

**Remediation:**
```javascript
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

**Use Cases:**
- Local development might use 3000
- CI/CD pipelines might use 8080
- Production might use 80 or 443
- Multiple services need different ports

---

### 2. **Test Data in Endpoints** (MEDIUM PRIORITY)
**Location:** `app.js`, lines 11-17  
**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Issues:**
- Mock user data is hardcoded in the application
- Test data exposed in production
- Cannot switch data sources without code changes
- Should come from a database, not hardcoded

**Remediation Options:**

**Option A: Use Environment Variable for Data Source**
```javascript
const DATA_SOURCE = process.env.DATA_SOURCE || 'mock'; // 'mock', 'database', 'api'

app.get('/users', (req, res) => {
  let users;

  if (DATA_SOURCE === 'mock') {
    users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
  } else if (DATA_SOURCE === 'database') {
    // Query database
    users = await db.query('SELECT * FROM users');
  }

  res.json(users);
});
```

**Option B: Move to Separate Config File**
```javascript
// config/data.js
const mockUsers = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

module.exports = { mockUsers };

// app.js
const { mockUsers } = require('./config/data');

app.get('/users', (req, res) => {
  res.json(mockUsers);
});
```

**Option C: Load from Environment Variable (Best for security)**
```javascript
// .env
USERS_DATA='[{"id":1,"name":"Alice","email":"alice@example.com"},{"id":2,"name":"Bob","email":"bob@example.com"}]'

