## Configuration Management Best Practices

### 1. Use a Configuration Module
```javascript
// config.js
const dotenv = require('dotenv');
dotenv.config();

const config = {
  app: {
    port: parseInt(process.env.PORT || '3000', 10),
    host: process.env.HOST || 'localhost',
    nodeEnv: process.env.NODE_ENV || 'development'
  },
  security: {
    corsOrigin: process.env.CORS_ORIGIN || 'http://localhost:3000',
    rateLimit: parseInt(process.env.RATE_LIMIT || '100', 10),
    rateLimitWindow: parseInt(process.env.RATE_LIMIT_WINDOW || '900000', 10)
  },
  api: {
    healthStatus: process.env.HEALTH_STATUS || 'ok',
    healthMessage: process.env.HEALTH_MESSAGE || 'healthy'
  }
};

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV'];
const missing = requiredEnvVars.filter(envVar => !process.env[envVar]);
if (missing.length > 0) {
  throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
}

module.exports = config;
```

### 2. Use Configuration Validation
```javascript
// config.js
const Joi = require('joi');

const envVarsSchema = Joi.object({
  NODE_ENV: Joi.string().valid('development', 'production', 'test').required(),
  PORT: Joi.number().port().default(3000),
  HOST: Joi.string().hostname().default('localhost'),
  CORS_ORIGIN: Joi.string().uri().required(),
  RATE_LIMIT: Joi.number().min(1).default(100),
  RATE_LIMIT_WINDOW: Joi.number().min(1000).default(900000),
}).unknown();

const { value: envVars, error } = envVarsSchema.validate(process.env);

if (error) {
  throw new Error(`Config validation error: ${error.message}`);
}

module.exports = envVars;
```

### 3. Use a Configuration Library
Consider using established libraries:
- `dotenv` - Load environment variables from `.env`
- `joi` - Validate environment variables
- `node-config` - Manage configuration files
- `convict` - Configuration management with schema validation

