// Improved version with environment variables
require('dotenv').config();

const express = require('express');
const app = express();

// Configuration from environment variables
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';
const API_PREFIX = process.env.API_PREFIX || '/api/v1';
const LOG_LEVEL = process.env.LOG_LEVEL || 'info';

// Parse mock users from environment or use defaults
const DEFAULT_USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

let mockUsers = DEFAULT_USERS;
try {
  if (process.env.MOCK_USERS) {
    mockUsers = JSON.parse(process.env.MOCK_USERS);
  }
} catch (error) {
  console.error('Failed to parse MOCK_USERS env variable, using defaults');
  mockUsers = DEFAULT_USERS;
}

// Health check endpoint
app.get(`${API_PREFIX}/health`, (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    uptime: process.uptime(),
  });
});

// Users endpoint
app.get(`${API_PREFIX}/users`, (req, res) => {
  res.json(mockUsers);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(`[${NODE_ENV}] Error:`, err.message);
  res.status(500).json({
    error: NODE_ENV === 'production' ? 'Internal Server Error' : err.message,
  });
});

// Start server
const server = app.listen(PORT, HOST, () => {
  console.log(`[${NODE_ENV}] Server running on ${HOST}:${PORT}`);
  console.log(`[${NODE_ENV}] API prefix: ${API_PREFIX}`);
  console.log(`[${NODE_ENV}] Log level: ${LOG_LEVEL}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Side-by-Side Comparison: Hardcoded vs. Environment Variables

## Port Configuration

### ❌ BEFORE (Hardcoded)
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Problems:**
- Port is fixed to 3000
- Will fail if port 3000 is in use
- Cannot run multiple instances on same machine
- Log message is misleading if environment changes

### ✅ AFTER (Environment Variable)
```javascript
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
});
```

**Benefits:**
- Flexible across environments
- Explicit fallback default
- Clear log output matching actual configuration
- Safe host binding

---

## Mock User Data

### ❌ BEFORE (Hardcoded)
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Problems:**
- Test data embedded in code
- Cannot change test data without code change
- Difficult to test with different data sets
- Not scalable for CI/CD

### ✅ AFTER (Environment Variable)
```javascript
const DEFAULT_USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

let mockUsers = DEFAULT_USERS;
try {
  if (process.env.MOCK_USERS) {
    mockUsers = JSON.parse(process.env.MOCK_USERS);
  }
} catch (error) {
  console.error('Failed to parse MOCK_USERS, using defaults');
}

app.get('/users', (req, res) => {
  res.json(mockUsers);
});
```

**Benefits:**
- Test data configurable without code changes
- Easy to test different scenarios
- Maintains secure defaults
- Error handling for malformed JSON

---

## Hardcoded Route Paths

### ❌ BEFORE
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', (req, res) => {
  res.json(mockUsers);
});
```

**Problems:**
- Cannot version API without code changes
- No flexibility for route prefixes
- Difficult to manage multiple API versions

### ✅ AFTER
```javascript
const API_PREFIX = process.env.API_PREFIX || '/api/v1';

app.get(`${API_PREFIX}/health`, (req, res) => {
  res.json({ status: 'ok' });
});

app.get(`${API_PREFIX}/users`, (req, res) => {
  res.json(mockUsers);
});
```

**Benefits:**
- Easy API versioning (/api/v2, etc.)
- Flexible route prefixing
- No code changes needed for deployment variations

---

## Environment Detection

### ❌ BEFORE (Not Handled)
```javascript
// No environment detection
console.log('Server running on port 3000');
```

**Problems:**
- Cannot differentiate behavior by environment
- No way to toggle features per environment
- Debugging production issues is harder

### ✅ AFTER
```javascript
const NODE_ENV = process.env.NODE_ENV || 'development';

console.log(`[${NODE_ENV}] Server running on port ${PORT}`);

// Can now use NODE_ENV for conditional logic
if (NODE_ENV === 'production') {
  // Use more restrictive settings
} else {
  // Use developer-friendly settings
}
```

**Benefits:**
- Environment-aware configuration
- Easier debugging and logging
- Can implement environment-specific features
- Better security posture in production

---

## Complete Configuration Object Pattern

### ❌ BEFORE (Scattered)
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

### ✅ AFTER (Centralized)
```javascript
// Configuration object at top of file
const config = {
  port: process.env.PORT || 3000,
  host: process.env.HOST || 'localhost',
  env: process.env.NODE_ENV || 'development',
  apiPrefix: process.env.API_PREFIX || '/api/v1',
  logLevel: process.env.LOG_LEVEL || 'info',
  cors: {
    origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  },
};

// Use config throughout app
app.listen(config.port, config.host, () => {
  console.log(`[${config.env}] Server running on ${config.host}:${config.port}`);
});

app.get(`${config.apiPrefix}/users`, (req, res) => {
  res.json(mockUsers);
});
```

**Benefits:**
- Single source of truth for configuration
- Easy to review all settings
- Easier to add new configuration
- Better maintainability

---

## Environment Variable Usage Examples

### Development
```bash
PORT=3000 HOST=localhost NODE_ENV=development node app.js
```

### Testing
```bash
PORT=3001 HOST=127.0.0.1 NODE_ENV=test MOCK_USERS='[{"id":1,"name":"Test","email":"test@test.com"}]' npm test
```

### Staging
```bash
PORT=8080 HOST=0.0.0.0 NODE_ENV=staging API_PREFIX=/api/v1 LOG_LEVEL=info node app.js
```

### Production (via environment)
```bash
export PORT=443
export HOST=0.0.0.0
export NODE_ENV=production
export API_PREFIX=/api/v1
export LOG_LEVEL=warn
node app.js
```

---

## Summary Table

| Item | Before | After | Impact |
|------|--------|-------|--------|
| Port | `3000` | `process.env.PORT \|\| 3000` | HIGH |
| Host | Not specified | `process.env.HOST \|\| localhost` | MEDIUM |
| Mock Data | Hardcoded | `process.env.MOCK_USERS` | MEDIUM |
| Routes | `/health`, `/users` | `` ${API_PREFIX}/health `` | LOW |
| Environment | Not handled | `process.env.NODE_ENV` | MEDIUM |
| Config | Scattered | Centralized object | MEDIUM |
| Flexibility | Low | High | HIGH |
| Security | Lower | Higher | MEDIUM |
| Maintainability | Low | High | HIGH |

---

## Migration Checklist

- [ ] Install dotenv: `npm install dotenv`
- [ ] Create `.env.example` file
- [ ] Update `.gitignore` to exclude `.env*`
- [ ] Refactor app.js with config object
- [ ] Test locally with different PORT values
- [ ] Test with custom MOCK_USERS
- [ ] Document environment setup
- [ ] Update CI/CD pipeline with env vars
- [ ] Verify logging shows correct configuration
- [ ] Remove old hardcoded version

