  // No protocol specification, defaults to HTTP
});
```

**Risk Level**: MEDIUM
**Issues**:
- No way to configure SSL/TLS certificates via environment
- Development uses HTTP but production should use HTTPS
- Server binding address not configurable (defaults to all interfaces)

**Fix**:
```javascript
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';

if (NODE_ENV === 'production') {
  const https = require('https');
  const fs = require('fs');

  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH)
  };

  https.createServer(options, app).listen(PORT, HOST, () => {
    console.log(`Secure server running on https://${HOST}:${PORT}`);
  });
