// Secure version of the application with security best practices implemented

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Helmet - Set security HTTP headers
app.use(helmet());

// 2. CORS - Configure cross-origin requests
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'HEAD', 'OPTIONS'],
  maxAge: 3600
}));

// 3. Logging - Use morgan for access logs
app.use(morgan('combined'));

// 4. Rate limiting - Prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiter to all routes
app.use(limiter);

// 5. Body parser middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================================================
// ROUTES
// ============================================================================

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real application, implement proper authorization checks here
  // Verify that the requesting user has permission to view user data

  // Return only necessary fields (email might be sensitive)
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    status: err.status || 500,
    timestamp: new Date().toISOString()
    // Don't expose stack trace to client
  });

  // Don't expose stack traces to clients
  const statusCode = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// Only start server if this module is run directly
if (require.main === module) {
  const server = app.listen(PORT, HOST, () => {
    console.log(`Server running on http://${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM received, shutting down gracefully...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  });
}

module.exports = app;

# Node.js Common Vulnerabilities Reference Guide

## OWASP Top 10 Web Application Vulnerabilities

### 1. Broken Access Control
**Status in this app:** ⚠️ Potential Risk

**What it is:**
- Users can access data/functionality they shouldn't have access to
- Missing authorization checks
- Horizontal privilege escalation (accessing other users' data)
- Vertical privilege escalation (accessing admin functions)

**Example in this app:**
```javascript
// ❌ VULNERABLE - No authorization check
app.get('/users', (req, res) => {
  // Anyone can access all users
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ✅ SECURE - Add authorization
app.get('/users', (req, res) => {
  if (!req.user || !req.user.isAdmin) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  res.json([...]);
});
```

---

### 2. Cryptographic Failures
**Status in this app:** 🔴 CRITICAL (Exposed Credentials)

**What it is:**
- Sensitive data exposed (credentials, PII)
- Data transmitted without encryption
- Weak or outdated encryption algorithms
- Secrets hardcoded in code

**Example in this app:**
```javascript
// ❌ CRITICAL - Credentials exposed in .env.test
DATABASE_URL=postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production

// ✅ SECURE - Use environment variables from secure source
const dbUrl = process.env.DATABASE_URL;
```

---

### 3. Injection
**Status in this app:** ⚠️ Potential Risk (if endpoints accept input)

**What it is:**
- SQL Injection
- Command Injection
- LDAP Injection
- NoSQL Injection
- Cross-Site Scripting (XSS)

**Example:**
```javascript
// ❌ VULNERABLE - SQL Injection
app.get('/users/:id', (req, res) => {
  const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
  // Attacker sends: /users/1; DROP TABLE users;--
  db.query(query);
});

// ✅ SECURE - Use parameterized queries
app.get('/users/:id', (req, res) => {
  const query = 'SELECT * FROM users WHERE id = $1';
  db.query(query, [req.params.id]);
});
```

---

### 4. Insecure Design
**Status in this app:** 🟠 HIGH

**What it is:**
- Missing security controls
- No rate limiting
- No input validation
- No error handling
- Design flaws

**Example:**
```javascript
// ❌ INSECURE - No security controls
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// ✅ SECURE - Add security controls
app.use(rateLimit({ max: 100, windowMs: 15 * 60 * 1000 }));
app.use(helmet());
app.use(express.json({ limit: '10kb' }));
```

---

### 5. Security Misconfiguration
**Status in this app:** 🟠 HIGH

**What it is:**
- Unpatched dependencies
- Default credentials
- Unnecessary features enabled
- Missing security headers
- Improper error handling

**Checks:**
```bash
# Check for vulnerable dependencies
npm audit

# Check security headers (production)
curl -I https://your-app.com | grep -i "X-"

# Check Express version
npm list express
```

---

### 6. Vulnerable & Outdated Components
**Status in this app:** ⚠️ Unknown (Need to run npm audit)

**What it is:**
- Using outdated packages with known vulnerabilities
- Dependencies with security patches not applied
- Transitive dependencies vulnerable

**Fix:**
```bash
npm audit
npm audit fix
npm update
npm outdated
```

---

### 7. Identification & Authentication Failures
**Status in this app:** ⚠️ Potential (No authentication implemented)

**What it is:**
- Weak password policies
- Credential stuffing attacks
- Brute force attacks
- Session management failures
- No MFA

**This app:**
- Currently has NO authentication
- Public endpoints accessible to anyone
- Should add authentication if handling sensitive data

---

### 8. Software & Data Integrity Failures
**Status in this app:** ⚠️ Potential Risk

**What it is:**
- Insecure CI/CD pipelines
- Unsigned updates
- No data validation on deserialization

**Recommendations:**
```bash
# Use npm ci instead of npm install in CI
npm ci

# Verify package integrity
npm install --audit-level=moderate
```

---

### 9. Logging & Monitoring Failures
**Status in this app:** 🟠 HIGH

**What it is:**
- Insufficient logging
- No security event logging
- No alerting mechanisms
- Logs not protected

**Fix:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// HTTP request logging
app.use(morgan('combined'));

// Application logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

logger.info('Security event', { event: 'login', userId: 123 });
```

---

### 10. Server-Side Request Forgery (SSRF)
**Status in this app:** ⚠️ Potential (if URLs are handled)

**What it is:**
- Application makes requests on behalf of attacker
- Can access internal resources
- Can interact with external services

**Example:**
```javascript
// ❌ VULNERABLE - User-controlled URL
app.get('/fetch', (req, res) => {
  const url = req.query.url;
  fetch(url).then(r => r.text()).then(data => res.send(data));
});

// ✅ SECURE - Whitelist allowed URLs
const ALLOWED_HOSTS = ['api.example.com'];
app.get('/fetch', (req, res) => {
  const url = new URL(req.query.url);
  if (!ALLOWED_HOSTS.includes(url.hostname)) {
    return res.status(403).json({ error: 'Not allowed' });
  }
  // fetch...
});
```

---

## Node.js-Specific Vulnerabilities

### 1. Prototype Pollution
**Risk Level:** HIGH

```javascript
// ❌ VULNERABLE - Merging user input into objects
const obj = {};
const user = JSON.parse(userInput);
Object.assign(obj, user);
// User can set: {"__proto__": {"isAdmin": true}}

// ✅ SECURE - Use Object.create(null) or safe merging
const obj = Object.create(null);
// Or use packages like flat-copy with validation
```

### 2. Regular Expression DoS (ReDoS)
**Risk Level:** MEDIUM

```javascript
// ❌ VULNERABLE - Complex regex on user input
const regex = /^(a+)+$/;
regex.test(userInput); // Can hang on input like "aaaaaaaaaaaaaaaaaaaaaaaaab"

// ✅ SECURE - Keep regexes simple or use timeout
const regex = /^[a]+$/;
regex.test(userInput);
```

### 3. Path Traversal
**Risk Level:** HIGH

```javascript
// ❌ VULNERABLE - User-controlled file path
app.get('/file', (req, res) => {
  const file = req.query.filename;
  res.sendFile(`./uploads/${file}`);
  // Attacker sends: /file?filename=../../etc/passwd
});

// ✅ SECURE - Validate and normalize paths
const path = require('path');
app.get('/file', (req, res) => {
  const file = req.query.filename;
  const fullPath = path.resolve('./uploads', file);

  if (!fullPath.startsWith(path.resolve('./uploads'))) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  res.sendFile(fullPath);
});
```

### 4. Denial of Service (DoS)
**Risk Level:** HIGH

**Types:**
- Large payload attacks
- Complex query attacks
- Zip bombs
- Algorithmic complexity attacks

```javascript
// ✅ SECURE - Add protections
const express = require('express');
const rateLimit = require('express-rate-limit');

app.use(express.json({ limit: '10kb' }));
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));
```

