// Improved version with environment variables and security best practices
const express = require('express');
const helmet = require('helmet');
require('dotenv').config(); // Load environment variables

const app = express();

// Security middleware
app.use(helmet());
app.use(express.json({ limit: '10kb' })); // Limit payload size

// Configuration from environment variables
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const APP_NAME = process.env.APP_NAME || 'MyApp';

// Mock database (in production, use actual database)
const mockUsers = process.env.NODE_ENV === 'production' 
  ? [] // Don't expose any test data in production
  : [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

app.get('/health', (req, res) => {
  // Only expose minimal info based on environment
  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
  };

  // Add environment info only in non-production
  if (NODE_ENV !== 'production') {
    healthData.app = APP_NAME;
    healthData.env = NODE_ENV;
  }

  res.json(healthData);
});

app.get('/users', (req, res) => {
  // Validate query parameters
  const limit = Math.min(parseInt(req.query.limit) || 10, 100); // Max 100
  const offset = parseInt(req.query.offset) || 0;

  // In production, implement proper authorization
  if (NODE_ENV === 'production' && !req.headers.authorization) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const users = mockUsers.slice(offset, offset + limit);
  res.json(users);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't expose error details in production
  if (NODE_ENV === 'production') {
    return res.status(500).json({ error: 'Internal server error' });
  }

  res.status(500).json({ 
    error: 'Internal server error',
    details: err.message 
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
