// Secure version of the application with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// ============================================
// Security Middleware
// ============================================

// Set security headers
app.use(helmet());

// Request logging
app.use(morgan('combined'));

// Rate limiting - prevent brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// CORS configuration (if needed)
// const cors = require('cors');
// app.use(cors({
//   origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
//   credentials: true
// }));

// ============================================
// Middleware for parsing
// ============================================

app.use(express.json());

// ============================================
// Authentication/Authorization Middleware
// ============================================

/**
 * Simple auth middleware - replace with proper JWT or session verification
 * In production, use:
 * - JWT tokens with RS256 signing
 * - OAuth2.0
 * - Session-based auth with secure cookies
 */
const authenticate = (req, res, next) => {
  // For health endpoint, you might skip auth
  if (req.path === '/health') {
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Missing or invalid authorization token'
    });
  }

  const token = authHeader.slice(7);

  // TODO: Verify token with your auth provider
  // Example: verifyJWT(token) or validateSessionToken(token)

  if (!token) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  // Store user info in request for later use
  // req.user = decodedToken;

  next();
};

// ============================================
// Routes
// ============================================

/**
 * Health check endpoint
 * Can be public (used by load balancers)
 * Returns minimal information
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

/**
 * Protected users endpoint
 * Requires authentication
 * Should include proper filtering/pagination
 */
app.get('/users', authenticate, (req, res) => {
  // TODO: Add input validation and pagination
  const limit = Math.min(parseInt(req.query.limit) || 10, 100);
  const offset = parseInt(req.query.offset) || 0;

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json({
    data: users.slice(offset, offset + limit),
    total: users.length,
    limit,
    offset
  });
});

// ============================================
// Error Handling Middleware
// ============================================

/**
 * 404 handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

/**
 * Global error handler
 * Must be defined last
 */
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  const statusCode = err.statusCode || 500;
  const response = {
    error: err.name || 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'An unexpected error occurred'
  };

  res.status(statusCode).json(response);
});

// ============================================
// Server Startup
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Original vs Secure Implementation - Side by Side Comparison

## 1. SECURITY HEADERS

### ❌ Original (app.js)
```javascript
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
// No security headers at all!
```
**Vulnerabilities:**
- No protection against clickjacking
- No MIME type sniffing protection
- No XSS protection headers
- Missing CSP headers
- No HSTS enforcement

### ✅ Secure (app_secure.js)
```javascript
const helmet = require('helmet');
const app = express();

app.use(helmet());
// Automatically sets:
// - X-Content-Type-Options: nosniff
// - X-Frame-Options: DENY
// - Strict-Transport-Security: max-age=15552000
// - X-XSS-Protection: 1; mode=block
// - Content-Security-Policy headers
```
**Protection:**
- ✅ Clickjacking protection via X-Frame-Options
- ✅ MIME sniffing protection
- ✅ XSS protection
- ✅ Comprehensive CSP policy
- ✅ HSTS enforcement

---

## 2. AUTHENTICATION & AUTHORIZATION

### ❌ Original (app.js)
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Anyone can access this endpoint!
// User PII (names, emails) publicly exposed
```
**Vulnerabilities:**
- No authentication required
- Exposes user PII without permission
- No authorization checks
- GDPR/CCPA violation
- Information disclosure vulnerability

### ✅ Secure (app_secure.js)
```javascript
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Missing or invalid authorization token'
    });
  }
  // Token verification would happen here
  next();
};

app.get('/users', authenticate, (req, res) => {
  // Only authenticated users can see this
  const limit = Math.min(parseInt(req.query.limit) || 10, 100);
  const offset = parseInt(req.query.offset) || 0;

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json({
    data: users.slice(offset, offset + limit),
    total: users.length,
    limit,
    offset
  });
});
```
**Protection:**
- ✅ Requires Bearer token authentication
- ✅ Authorization check before access
- ✅ Pagination to limit data exposure
- ✅ GDPR/CCPA compliant
- ✅ Data protection via access control

---

## 3. RATE LIMITING & DoS PROTECTION

### ❌ Original (app.js)
```javascript
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json(users);
});

// No rate limiting - vulnerable to:
// - Brute force attacks
// - DoS attacks
// - Credential stuffing
// - Spam
```

**Vulnerabilities:**
- Unlimited requests per IP
- No protection against brute force
- No DoS protection
- Attackers can enumerate users
- High resource consumption possible

### ✅ Secure (app_secure.js)
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 100,                   // Max 100 requests per IP
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,      // Send rate limit info
  legacyHeaders: false,       // Disable X-RateLimit
});

app.use(limiter);

app.get('/users', authenticate, (req, res) => {
  // Limited to 100 requests per 15 minutes
  res.json(users);
});
```

**Protection:**
- ✅ 100 requests per 15 minutes per IP
- ✅ Brute force protection
- ✅ DoS mitigation
- ✅ Rate limit headers returned
- ✅ Configurable per endpoint if needed

---

## 4. LOGGING & MONITORING

### ❌ Original (app.js)
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Only startup message, no request logging
// No error logging
// No audit trail
// No visibility into security events
```

**Vulnerabilities:**
- No request logging
- No audit trail
- Cannot track attacks
- Cannot troubleshoot issues
- No security monitoring

### ✅ Secure (app_secure.js)
```javascript
const morgan = require('morgan');

// Log all HTTP requests in standard format
app.use(morgan('combined'));

// Global error logging
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' 
      ? err.stack 
      : undefined
  });
  // ... error response
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV}`);
});
```

**Protection:**
- ✅ HTTP request logging
- ✅ Error tracking and logging
- ✅ Audit trail for investigations
- ✅ Security event visibility
- ✅ Performance monitoring

---

## 5. SECRET MANAGEMENT

### ❌ Original (Configuration)
```
