  },

  // Validation
  validate() {
    if (this.isProduction && !this.jwt.secret) {
      throw new Error('JWT_SECRET is required in production');
    }
    if (this.isProduction && this.cors.origins.includes('*')) {
      throw new Error('Wildcard CORS not allowed in production');
    }
  }
};

// Usage in app.js
