// Secure version of app.js with best practices implemented
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// Load environment variables
require('dotenv').config();

const app = express();

// Configuration from environment variables
const port = process.env.PORT || 3000;
const allowedOrigin = process.env.ALLOWED_ORIGIN || 'http://localhost:3000';
const nodeEnv = process.env.NODE_ENV || 'development';

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Security headers
app.use(helmet());

// CORS with explicit configuration
app.use(cors({
  origin: allowedOrigin,
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * No authentication required
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: nodeEnv
  });
});

/**
 * Users endpoint
 * TODO: Add authentication middleware before deploying to production
 * Currently exposes PII (Personally Identifiable Information)
 */
app.get('/users', (req, res) => {
  // TODO: Implement authentication
  // TODO: Add input validation for query parameters
  // TODO: Implement proper authorization checks
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ============================================
// ERROR HANDLING
// ============================================

/**
 * 404 Not Found Handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

/**
 * Global Error Handler
 * Should be the last middleware
 */
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: nodeEnv === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString()
  });

  // Don't expose error details in production
  const statusCode = err.statusCode || 500;
  const message = nodeEnv === 'development' ? err.message : 'Internal Server Error';

  res.status(statusCode).json({
    error: 'Internal Server Error',
    message: message,
    ...(nodeEnv === 'development' && { stack: err.stack })
  });
});

// ============================================
// SERVER START
// ============================================

app.listen(port, () => {
  console.log(`Server running on port ${port}`);
  console.log(`Environment: ${nodeEnv}`);
  console.log(`CORS origin: ${allowedOrigin}`);
});

module.exports = app;

