 */
app.get('/users', (req, res) => {
  // Feature flag: can disable this endpoint without code changes
  if (!config.features.enableUserEndpoint) {
    return res.status(404).json({ error: 'Endpoint not found' });
  }

  // Return configured users or empty array
  if (!config.defaultUsers || config.defaultUsers.length === 0) {
    return res.status(404).json({
      error: 'No users available',
      note: 'Set DEFAULT_USERS environment variable',
    });
  }

  res.json(config.defaultUsers);
});

/**
 * Error handling middleware
 */
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({
    error: config.server.nodeEnv === 'production'
      ? 'Internal Server Error'
      : err.message,
  });
});

// Start server using configuration values (no hardcoded values)
app.listen(config.server.port, config.server.host, () => {
  const message = `Server running on ${config.server.host}:${config.server.port} (${config.server.nodeEnv})`;
