/**
 * Centralized Configuration Module
 * Loads and validates environment variables
 * 
 * DO NOT COMMIT SECRETS TO THIS FILE
 * Use .env files and environment variables instead
 */

require('dotenv').config();

// Validate and retrieve environment variables with defaults
const config = {
  // Server Configuration
  port: parseInt(process.env.PORT || '3000'),
  host: process.env.HOST || '0.0.0.0',
  nodeEnv: process.env.NODE_ENV || 'development',

  // Database Configuration
  database: {
    url: process.env.DATABASE_URL || 'postgres://localhost:5432/myapp',
    pool: {
      min: parseInt(process.env.DB_POOL_MIN || '2'),
      max: parseInt(process.env.DB_POOL_MAX || '10'),
    },
    ssl: process.env.DATABASE_SSL === 'true',
  },

  // Security Configuration
  cors: {
    origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
    credentials: process.env.CORS_CREDENTIALS === 'true',
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  },

  // Logging Configuration
  logging: {
    level: process.env.LOG_LEVEL || 'info',
    format: process.env.LOG_FORMAT || 'combined',
  },

  // Rate Limiting Configuration
  rateLimit: {
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW || '900000'), // 15 minutes
    max: parseInt(process.env.RATE_LIMIT_MAX || '100'),
    skipSuccessfulRequests: process.env.RATE_LIMIT_SKIP === 'true',
  },

  // Session Configuration
  session: {
    secret: process.env.SESSION_SECRET || 'dev-secret-change-in-production',
    timeout: parseInt(process.env.SESSION_TIMEOUT || '3600000'), // 1 hour
  },

  // Feature Flags
  features: {
    enableDetailedErrors: process.env.ENABLE_DETAILED_ERRORS === 'true',
    enableMetrics: process.env.ENABLE_METRICS === 'true',
  },
};

/**
 * Validate required configuration
 * Fails fast if critical config is missing or invalid
 */
function validateConfig() {
  const errors = [];

  // Validate PORT
  if (isNaN(config.port) || config.port < 1 || config.port > 65535) {
    errors.push(`Invalid PORT: ${process.env.PORT} (must be 1-65535)`);
  }

  // Validate NODE_ENV
  const validEnvs = ['development', 'staging', 'production', 'test'];
  if (!validEnvs.includes(config.nodeEnv)) {
    errors.push(`Invalid NODE_ENV: ${config.nodeEnv} (must be one of: ${validEnvs.join(', ')})`);
  }

  // Validate DATABASE_URL
  if (!config.database.url) {
    errors.push('DATABASE_URL is required');
  }

  // Production-specific validations
  if (config.nodeEnv === 'production') {
    if (!process.env.DATABASE_URL) {
      errors.push('DATABASE_URL must be explicitly set in production');
    }
    if (config.session.secret === 'dev-secret-change-in-production') {
      errors.push('SESSION_SECRET must be set to a strong value in production');
    }
    if (!process.env.CORS_ORIGIN || process.env.CORS_ORIGIN === 'http://localhost:3000') {
      errors.push('CORS_ORIGIN must be set to production domain in production');
    }
  }

  if (errors.length > 0) {
    console.error('\n❌ Configuration Validation Errors:');
    errors.forEach((err) => console.error(`  - ${err}`));
    console.error('\n');
    process.exit(1);
  }
}

// Run validation on module load
validateConfig();

// Log startup configuration (without secrets)
function logConfiguration() {
  const displayConfig = {
    environment: config.nodeEnv,
    port: config.port,
    host: config.host,
    database: config.database.url.split('@')[0] + '@***', // Mask credentials
    corsOrigin: config.cors.origin,
    logLevel: config.logging.level,
  };

  console.log('✅ Server Configuration Loaded:');
  console.log(JSON.stringify(displayConfig, null, 2));
}

if (config.nodeEnv !== 'test') {
  logConfiguration();
}

module.exports = config;

/**
 * Updated app.js using configuration management
 * All hardcoded values replaced with environment variables
 */

const express = require('express');
const config = require('./config');

const app = express();

/**
 * Health check endpoint (no auth required)
 * Returns basic server status
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: config.nodeEnv,
    uptime: process.uptime(),
  });
});

/**
 * Users endpoint (protected)
 * TODO: Add authentication middleware
 * TODO: Connect to actual database
 */
app.get('/users', (req, res) => {
  // TODO: Add auth check
  // if (!req.user || !req.user.isAdmin) {
  //   return res.status(403).json({ error: 'Unauthorized' });
  // }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  const statusCode = err.status || 500;
  const response = {
    message: 'Internal Server Error',
  };

  // Only include stack trace in development
  if (config.nodeEnv === 'development') {
    response.error = err.message;
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

/**
 * 404 handler
 */
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Start server using configuration
const server = app.listen(config.port, config.host, () => {
  console.log(`🚀 Server running on http://${config.host}:${config.port}`);
  console.log(`📝 Environment: ${config.nodeEnv}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

