// Secure version of app.js with proper environment configuration
// and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Security: Use environment variables with sensible defaults
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';
const NODE_ENV = process.env.NODE_ENV || 'development';

// Security: Apply security headers
app.use(helmet());

// Security: Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Security: Only load mock data in development/test
let mockUsers = [];
if (NODE_ENV !== 'production') {
  mockUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Security: Only expose users endpoint in non-production or with explicit flag
if (NODE_ENV !== 'production' || process.env.ENABLE_MOCK_DATA === 'true') {
  app.get('/users', (req, res) => {
    res.json(mockUsers);
  });
}

// Security: Graceful shutdown handlers
process.on('SIGTERM', () => {
  console.log('[SIGTERM] Received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('[SIGINT] Received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
