# Hardcoded Values Analysis Report

## Issues Found in `app.js`

### 1. **Hardcoded Port Number**
**Severity:** MEDIUM  
**Location:** Line 18 in `app.js`

**Current Code:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Issues:**
- Port is hardcoded to `3000`
- Cannot easily change port for different environments (dev, staging, production)
- Conflicts with other services using port 3000
- Makes containerization and deployment inflexible

**Fix:**
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

---

### 2. **Hardcoded Mock User Data**
**Severity:** MEDIUM  
**Location:** Lines 13-14 in `app.js`

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Issues:**
- Sample user data is hardcoded (security anti-pattern)
- Example email addresses are exposed in source code
- Not configurable for different environments
- Test data mixed with application logic
- Should come from environment or database in production

**Fix:**
```javascript
// Load from environment or use default for development only
const DEFAULT_USERS = JSON.parse(process.env.MOCK_USERS || JSON.stringify([
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
]));

app.get('/users', (req, res) => {
  // Only return mock data in development
  if (process.env.NODE_ENV !== 'production') {
    res.json(DEFAULT_USERS);
  } else {
    res.status(404).json({ error: 'Not found' });
  }
});
```

**Better Approach:**
In production, fetch data from a database instead of using mock data.

---

### 3. **Missing Environment Configuration**
**Severity:** HIGH  
**Location:** Entire application

**Missing Hardcoded Values That Should Be Environment Variables:**

#### A. **Host/Bind Address**
Currently defaults to all interfaces but should be configurable:
```javascript
const HOST = process.env.HOST || '0.0.0.0';
app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
});
```

#### B. **Node Environment**
Should explicitly set NODE_ENV:
```javascript
const NODE_ENV = process.env.NODE_ENV || 'development';
```

#### C. **Logging Level**
Should be configurable:
```javascript
const LOG_LEVEL = process.env.LOG_LEVEL || 'info';
```

#### D. **API Version/Prefix**
```javascript
const API_PREFIX = process.env.API_PREFIX || '/api/v1';
```

#### E. **CORS Settings**
Should be environment-based:
```javascript
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
```

---

## Recommended `.env` File Template

Create `.env.example` (commit to repo):
```env
# Server Configuration
PORT=3000
HOST=0.0.0.0
NODE_ENV=development

# Logging
LOG_LEVEL=info

# API Configuration
API_PREFIX=/api/v1
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:3001

# Database (when added)
DATABASE_URL=postgres://user:password@localhost:5432/mydb

# External Services (when added)
AWS_ACCESS_KEY_ID=
AWS_SECRET_ACCESS_KEY=
ANTHROPIC_API_KEY=
STRIPE_SECRET_KEY=
LOGFIRE_TOKEN=

# Feature Flags
ENABLE_MOCK_DATA=true
MOCK_USERS=[{"id":1,"name":"Alice","email":"alice@example.com"},{"id":2,"name":"Bob","email":"bob@example.com"}]
```

---

## Improved `app.js` with Environment Variables

Here's a refactored version:

```javascript
require('dotenv').config();

const express = require('express');
const app = express();

// Configuration from environment
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';
const NODE_ENV = process.env.NODE_ENV || 'development';
const ENABLE_MOCK_DATA = process.env.ENABLE_MOCK_DATA === 'true';

// Mock data - only for development/testing
const DEFAULT_USERS = ENABLE_MOCK_DATA 
  ? JSON.parse(process.env.MOCK_USERS || JSON.stringify([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]))
  : [];

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV 
  });
});

// Users endpoint
app.get('/users', (req, res) => {
  if (NODE_ENV === 'production') {
    res.status(404).json({ error: 'Not found' });
  } else if (ENABLE_MOCK_DATA) {
    res.json(DEFAULT_USERS);
  } else {
    res.status(503).json({ error: 'Service unavailable' });
  }
});

// Error handling
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(err.status || 500).json({
    message: NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message
  });
});

// Start server
const server = app.listen(PORT, HOST, () => {
  console.log(`[${NODE_ENV}] Server running at http://${HOST}:${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;
```

---

## Summary Table

| Hardcoded Value | Location | Severity | Should Be |
|---|---|---|---|
| `3000` (port) | Line 18 | MEDIUM | `process.env.PORT` |
| Mock user data | Lines 13-14 | MEDIUM | `process.env.MOCK_USERS` or database |
| `0.0.0.0` (implicit) | Line 18 | LOW | `process.env.HOST` |
| No NODE_ENV | Entire app | MEDIUM | `process.env.NODE_ENV` |
| No HOST config | Entire app | LOW | `process.env.HOST` |

---

## Implementation Checklist

- [ ] Install `dotenv`: `npm install dotenv`
- [ ] Create `.env.example` with all configuration options
- [ ] Add `.env` to `.gitignore`
- [ ] Update `app.js` to use environment variables
- [ ] Test with different `.env` configurations
- [ ] Document environment variables in README
- [ ] Set up environment-specific config for dev, staging, production
- [ ] Validate required environment variables on startup
- [ ] Add configuration logging (hide sensitive values)

---

## Best Practices

1. **Never commit `.env` files** - Only commit `.env.example`
2. **Validate on startup** - Fail fast if required env vars are missing
3. **Use sensible defaults** - For non-sensitive, non-critical values only
4. **Log configuration** - On startup, log config (except secrets)
5. **Separate concerns** - Configuration, business logic, data access layers
6. **Use a config module** - Centralize all environment variable reading

// Improved application with environment variable configuration
require('dotenv').config();

const express = require('express');
const app = express();

// ===== Configuration from Environment Variables =====
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';
const NODE_ENV = process.env.NODE_ENV || 'development';
const ENABLE_MOCK_DATA = process.env.ENABLE_MOCK_DATA === 'true';
const LOG_LEVEL = process.env.LOG_LEVEL || 'info';

// ===== Mock Data Configuration =====
// Only used in development/testing when enabled
const DEFAULT_USERS = ENABLE_MOCK_DATA 
  ? JSON.parse(process.env.MOCK_USERS || JSON.stringify([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]))
  : [];

// ===== Logging Helper =====
const log = (level, message, data = '') => {
  const levels = { error: 0, warn: 1, info: 2, debug: 3 };
  const currentLevel = levels[LOG_LEVEL] || 2;

  if (levels[level] <= currentLevel) {
    console.log(`[${new Date().toISOString()}] [${level.toUpperCase()}] ${message}`, data);
  }
};

// ===== Application Initialization Logging =====
log('info', `Starting application in ${NODE_ENV} environment`);
log('info', `Configuration loaded:`, {
  port: PORT,
  host: HOST,
  mockDataEnabled: ENABLE_MOCK_DATA,
  logLevel: LOG_LEVEL
});

// ===== Routes =====

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    uptime: process.uptime()
  });
});

/**
 * Users endpoint
 * GET /users
 */
app.get('/users', (req, res) => {
  log('debug', 'GET /users request received');

  // Production: don't expose user data via simple API
  if (NODE_ENV === 'production') {
    log('warn', 'Mock users endpoint accessed in production');
    return res.status(404).json({ error: 'Not found' });
  }

  // Development: return mock data if enabled
  if (ENABLE_MOCK_DATA) {
    log('debug', `Returning ${DEFAULT_USERS.length} mock users`);
    return res.json(DEFAULT_USERS);
  }

  // Mock data disabled
  log('warn', 'Mock users endpoint accessed but mock data is disabled');
  res.status(503).json({ error: 'Service unavailable' });
});

// ===== Error Handling Middleware =====
app.use((err, req, res, next) => {
  log('error', `Error occurred: ${err.message}`, err.stack);

  const statusCode = err.status || 500;
  const response = {
    message: NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message,
    timestamp: new Date().toISOString()
  };

  // Include stack trace only in development
  if (NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ===== 404 Handler =====
app.use((req, res) => {
  log('warn', `404 Not Found: ${req.method} ${req.path}`);
  res.status(404).json({ error: 'Not found' });
});

// ===== Server Startup =====
const server = app.listen(PORT, HOST, () => {
  const url = `http://${HOST}:${PORT}`;
  log('info', `Server is listening at ${url}`);
  log('info', `Health check: ${url}/health`);
  if (ENABLE_MOCK_DATA && NODE_ENV !== 'production') {
    log('info', `Mock users endpoint: ${url}/users`);
  }
});

// ===== Graceful Shutdown =====
process.on('SIGTERM', () => {
  log('info', 'SIGTERM signal received: closing HTTP server');
  server.close(() => {
    log('info', 'HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  log('info', 'SIGINT signal received: closing HTTP server');
  server.close(() => {
    log('info', 'HTTP server closed');
    process.exit(0);
  });
});

// ===== Uncaught Exception Handler =====
process.on('uncaughtException', (err) => {
  log('error', 'Uncaught Exception:', err);
  process.exit(1);
});

module.exports = app;

/**
 * Configuration Validator
 * Validates required environment variables on application startup
 * Usage: require('./config.validator') in your app
 */

require('dotenv').config();

// Define required environment variables for different environments
const REQUIRED_ENV_VARS = {
  all: ['NODE_ENV', 'PORT'],
  development: [],
  production: [
    'NODE_ENV',
    'PORT',
    'LOG_LEVEL'
  ]
};

/**
 * Validate that all required environment variables are set
 * @throws {Error} If any required environment variable is missing
 */
function validateEnvironment() {
  const nodeEnv = process.env.NODE_ENV || 'development';

  // Get all required vars for current environment
  const requiredVars = [
    ...REQUIRED_ENV_VARS.all,
    ...(REQUIRED_ENV_VARS[nodeEnv] || [])
  ];

  const missing = [];
  const sensitive = ['SECRET', 'KEY', 'TOKEN', 'PASSWORD', 'API_KEY'];

  for (const variable of requiredVars) {
    if (!process.env[variable]) {
      missing.push(variable);
    }
  }

  if (missing.length > 0) {
    console.error('❌ Missing required environment variables:');
    missing.forEach(variable => {
      console.error(`   - ${variable}`);
    });
    console.error('\nPlease check your .env file or environment configuration.');
    process.exit(1);
  }

  // Log loaded configuration (hide sensitive values)
  console.log('✅ Environment configuration loaded:');

  const allVars = Object.keys(process.env)
    .filter(key => !sensitive.some(s => key.includes(s)))
    .sort();

  allVars.forEach(variable => {
    if (!['PATH', 'HOME', 'USER', 'SHELL', 'TERM'].includes(variable)) {
      console.log(`   ${variable}=${process.env[variable]}`);
    }
  });

  console.log('   (Sensitive values hidden)\n');
}

// Run validation
validateEnvironment();

module.exports = { validateEnvironment };

