# Hardcoded Values - Implementation Guide

## Overview
This document provides step-by-step instructions to fix hardcoded configuration values in the application and externalize them to environment variables.

---

## Issues Found & Fixes

### 1. PORT NUMBER (Priority 1 - HIGH) 🔴

**Problem Location:** `app.js:18`
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Why It's a Problem:**
- Can't change port without modifying code
- Breaks containerized deployments
- Prevents running multiple instances
- Non-compliant with 12-factor app principles

**Fix Implementation:**

```javascript
// app.js

const express = require('express');
const app = express();

// ... your routes ...

// FIXED: Externalize port and host
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
});

module.exports = app;
```

**Environment Variables Needed:**
```env
PORT=3000
HOST=localhost
```

**Time to Fix:** 5 minutes

---

### 2. CORS ALLOWED ORIGINS (Priority 2 - MEDIUM) 🟡

**Problem Location:** `app.secure.js:11`
```javascript
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  // Hardcoded fallback!
}));
```

**Why It's a Problem:**
- Hardcoded fallback defeats the purpose
- Production origin shouldn't be hardcoded
- Security risk in production deployment

**Fix Implementation:**

```javascript
// app.secure.js

const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || [];

// Production safety check
if (allowedOrigins.length === 0 && process.env.NODE_ENV === 'production') {
  throw new Error('ALLOWED_ORIGINS environment variable is required in production');
}

app.use(cors({
  // In development, allow all; in production, require explicit list
  origin: allowedOrigins.length > 0 ? allowedOrigins : true,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  optionsSuccessStatus: 200
}));
```

**Environment Variables Needed:**
```env
# Development
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:3001

# Staging
ALLOWED_ORIGINS=https://staging.example.com

# Production
ALLOWED_ORIGINS=https://example.com,https://www.example.com
```

**Time to Fix:** 10 minutes

---

### 3. RATE LIMITING CONFIGURATION (Priority 2 - MEDIUM) 🟡

**Problem Location:** `app.secure.js:15-23`
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // Hardcoded
  max: 100,                   // Hardcoded
  message: 'Too many requests, please try again later.'
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,   // Hardcoded
  max: 5,                      // Hardcoded
});
```

**Why It's a Problem:**
- Can't adjust rates per environment
- Production rates may need to be more/less strict
- Requires code change to scale

**Fix Implementation:**

```javascript
// app.secure.js

// Externalize rate limiting configuration
const RATE_LIMIT_WINDOW_MS = parseInt(
  process.env.RATE_LIMIT_WINDOW_MS || '900000', 
  10
); // 15 minutes default
const RATE_LIMIT_MAX = parseInt(
  process.env.RATE_LIMIT_MAX || '100', 
  10
);
const STRICT_LIMIT_MAX = parseInt(
  process.env.STRICT_LIMIT_MAX || '5', 
  10
);

const limiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: RATE_LIMIT_MAX,
  message: 'Too many requests, please try again later.'
});

const strictLimiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: STRICT_LIMIT_MAX,
  message: 'Too many requests, please try again later.'
});

// Use accordingly
app.use(limiter);
// app.post('/login', strictLimiter, loginHandler);
```

**Environment Variables Needed:**
```env
# Development - more permissive
RATE_LIMIT_WINDOW_MS=900000
RATE_LIMIT_MAX=1000
STRICT_LIMIT_MAX=50

# Staging - moderate
RATE_LIMIT_WINDOW_MS=900000
RATE_LIMIT_MAX=500
STRICT_LIMIT_MAX=20

# Production - strict
RATE_LIMIT_WINDOW_MS=900000
RATE_LIMIT_MAX=100
STRICT_LIMIT_MAX=5
```

**Time to Fix:** 20 minutes

---

### 4. JSON PAYLOAD SIZE LIMIT (Priority 2 - MEDIUM) 🟡

**Problem Location:** `app.secure.js:29`
```javascript
app.use(express.json({ limit: '10kb' })); // Hardcoded
```

**Why It's a Problem:**
- May need adjustment based on API requirements
- Different endpoints may need different limits
- Can't change without code modification

**Fix Implementation:**

```javascript
// app.secure.js

const JSON_LIMIT = process.env.JSON_LIMIT || '10kb';

app.use(express.json({ limit: JSON_LIMIT }));

// For specific routes needing different limits:
app.post('/upload', express.json({ limit: '50mb' }), uploadHandler);
```

**Environment Variables Needed:**
```env
# Development - generous
JSON_LIMIT=50mb

# Production - strict
JSON_LIMIT=10kb
```

**Time to Fix:** 10 minutes

---

### 5. LOGGING CONFIGURATION (Priority 2 - MEDIUM) 🟡

**Problem Location:** `app.secure.js:84-86`
```javascript
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);     // Always logs
  console.log(`Environment: ${process.env.NODE_ENV}`);  // Always logs
});
```

**Why It's a Problem:**
- No control over logging output
- Produces too much noise in production
- Can't adjust log verbosity

**Fix Implementation:**

```javascript
// app.secure.js

const LOG_LEVEL = process.env.LOG_LEVEL || 'info';

const server = app.listen(PORT, HOST, () => {
  if (LOG_LEVEL !== 'silent') {
    console.log(`Server running on ${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV}`);
  }
});

// For structured logging (recommended):
const logger = {
  debug: (msg) => LOG_LEVEL === 'debug' && console.log('[DEBUG]', msg),
  info: (msg) => ['info', 'debug'].includes(LOG_LEVEL) && console.log('[INFO]', msg),
  warn: (msg) => ['warn', 'info', 'debug'].includes(LOG_LEVEL) && console.log('[WARN]', msg),
  error: (msg) => console.error('[ERROR]', msg) // Always show errors
};

// Usage:
logger.debug('This only shows in debug mode');
logger.info('Server started');
logger.error('An error occurred');
```

**Environment Variables Needed:**
```env
# Development
LOG_LEVEL=debug

# Staging
LOG_LEVEL=info

# Production
LOG_LEVEL=warn
```

**Time to Fix:** 15 minutes

---

### 6. MOCK USER DATA (Priority 3 - DATA) 🟡

**Problem Location:** `app.js:10-14`
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },  // Hardcoded
    { id: 2, name: 'Bob', email: 'bob@example.com' },      // Hardcoded
  ]);
});
```

**Why It's a Problem:**
- Test data in production code
- Not externalized
- Email addresses exposed
- Should connect to database

**Fix Implementation (with database):**

```javascript
// app.js
const pg = require('pg');

const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL
});

app.get('/users', async (req, res) => {
  try {
    // Query database instead of returning hardcoded data
    const result = await pool.query('SELECT id, name FROM users ORDER BY id');
    res.json(result.rows);
  } catch (err) {
    console.error('Database error:', err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});
```

**Alternative (keep mock data for development):**

```javascript
// app.js

// Use mock data only in development
const getMockUsers = () => [
  { id: 1, name: 'Alice' },
  { id: 2, name: 'Bob' }
];

app.get('/users', async (req, res) => {
  try {
    if (process.env.NODE_ENV === 'development' && !process.env.DATABASE_URL) {
      // Use mock data for development
      return res.json(getMockUsers());
    }

    // Use real database
    const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });
    const result = await pool.query('SELECT id, name FROM users');
    res.json(result.rows);
  } catch (err) {
    console.error('Error:', err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});
```

**Environment Variables Needed:**
```env
# Development - no database
NODE_ENV=development
DATABASE_URL=

# Development - with database
NODE_ENV=development
DATABASE_URL=postgres://user:password@localhost:5432/devdb

# Production
NODE_ENV=production
DATABASE_URL=postgres://user:password@prod-db.example.com:5432/proddb
```

**Time to Fix:** 1-2 hours (if implementing database integration)

---

### 7. JWT CONFIGURATION (Priority 3 - FUTURE) 🟡

**When implementing JWT authentication:**

```javascript
// Auth middleware
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET;
const JWT_EXPIRY = process.env.JWT_EXPIRY || '1h';

if (!JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is required');
}

function generateToken(user) {
  return jwt.sign(
    { id: user.id, email: user.email },
    JWT_SECRET,
    { expiresIn: JWT_EXPIRY }
  );
}

function verifyToken(token) {
  try {
    return jwt.verify(token, JWT_SECRET);
  } catch (err) {
    return null;
  }
}

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const decoded = verifyToken(token);
  if (!decoded) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }

  req.user = decoded;
  next();
}

module.exports = { generateToken, verifyToken, authMiddleware };
```

**Environment Variables Needed:**
```env
# Development
JWT_SECRET=dev-secret-key-change-in-production
JWT_EXPIRY=7d

# Production
JWT_SECRET=your-very-secure-random-secret-key-here
JWT_EXPIRY=1h
JWT_REFRESH_EXPIRY=7d
```

**Time to Fix:** 2-3 hours (when implementing)

