// Fully configurable Express.js application
// All hardcoded values are externalized to environment variables
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============ CONFIGURATION MANAGEMENT ============

// Helper function to get environment variable with validation
const getEnvVar = (name, defaultValue, type = 'string') => {
  const value = process.env[name] ?? defaultValue;

  if (type === 'int') return parseInt(value, 10);
  if (type === 'bool') return value === 'true';
  if (type === 'json') return JSON.parse(value);

  return value;
};

// Validate required environment variables for production
const validateProductionConfig = () => {
  if (process.env.NODE_ENV === 'production') {
    const required = ['API_TOKEN', 'ALLOWED_ORIGINS'];
    const missing = required.filter(v => !process.env[v]);

    if (missing.length > 0) {
      throw new Error(`Missing required environment variables in production: ${missing.join(', ')}`);
    }
  }
};

// Configuration object
const config = {
  // Server
  port: getEnvVar('PORT', '3000', 'int'),
  host: getEnvVar('HOST', '0.0.0.0'),
  nodeEnv: getEnvVar('NODE_ENV', 'development'),
  appVersion: getEnvVar('APP_VERSION', '1.0.0'),

  // Security
  apiToken: getEnvVar('API_TOKEN', 'dev-token-change-in-production'),
  allowUnauthenticated: getEnvVar('ALLOW_UNAUTHENTICATED', 'false', 'bool'),
  allowedOrigins: getEnvVar('ALLOWED_ORIGINS', 'http://localhost:3000').split(','),

  // Rate Limiting
  rateLimitWindowMs: getEnvVar('RATE_LIMIT_WINDOW_MS', '900000', 'int'), // 15 minutes
  rateLimitMaxRequests: getEnvVar('RATE_LIMIT_MAX_REQUESTS', '100', 'int'),
  rateLimitMessage: getEnvVar('RATE_LIMIT_MESSAGE', 'Too many requests from this IP, please try again later.'),

  // Request Handling
  requestSizeLimit: getEnvVar('REQUEST_SIZE_LIMIT', '10kb'),
  queryMinLimit: getEnvVar('QUERY_MIN_LIMIT', '1', 'int'),
  queryMaxLimit: getEnvVar('QUERY_MAX_LIMIT', '100', 'int'),

  // Logging
  morganFormat: getEnvVar('MORGAN_FORMAT', 'combined'),
  logLevel: getEnvVar('LOG_LEVEL', 'info'),

  // Error Messages
  errorMessages: {
    unauthorized: getEnvVar('ERROR_MSG_UNAUTHORIZED', 'Access token required'),
    forbidden: getEnvVar('ERROR_MSG_FORBIDDEN', 'Invalid or expired token'),
    notFound: getEnvVar('ERROR_MSG_NOT_FOUND', 'Not Found'),
    serverError: getEnvVar('ERROR_MSG_SERVER_ERROR', 'Internal Server Error'),
    invalidInput: getEnvVar('ERROR_MSG_INVALID_INPUT', 'Invalid input provided'),
  },

  // Data
  useMockData: getEnvVar('USE_MOCK_DATA', 'true', 'bool'),
  mockUsers: getEnvVar('MOCK_USERS', '[{"id":1,"name":"Alice"},{"id":2,"name":"Bob"}]', 'json'),
};

// Validate production configuration
validateProductionConfig();

// Log configuration on startup (excluding sensitive values)
console.log(`[${new Date().toISOString()}] Configuration loaded:`, {
  port: config.port,
  host: config.host,
  nodeEnv: config.nodeEnv,
  appVersion: config.appVersion,
  allowedOrigins: config.allowedOrigins,
  rateLimitMaxRequests: config.rateLimitMaxRequests,
  requestSizeLimit: config.requestSizeLimit,
  useMockData: config.useMockData,
});

// ============ SECURITY MIDDLEWARE ============

// 1. Security headers with Helmet
app.use(helmet());

// 2. CORS configuration
app.use(cors({
  origin: config.allowedOrigins,
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 3. Request size limits (externalized)
app.use(express.json({ limit: config.requestSizeLimit }));
app.use(express.urlencoded({ limit: config.requestSizeLimit, extended: true }));

// 4. Rate limiting (fully configurable)
const limiter = rateLimit({
  windowMs: config.rateLimitWindowMs,
  max: config.rateLimitMaxRequests,
  message: config.rateLimitMessage,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 5. Request logging (configurable format)
app.use(morgan(config.morganFormat));

// ============ AUTHENTICATION MIDDLEWARE ============

const authenticateToken = (req, res, next) => {
  // Allow unauthenticated access if explicitly enabled
  if (config.allowUnauthenticated) {
    return next();
  }

  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: config.errorMessages.unauthorized });
  }

  if (token === config.apiToken) {
    next();
  } else {
    res.status(403).json({ error: config.errorMessages.forbidden });
  }
};

// ============ DATA LAYER ============

// Mock data function with configuration support
const getMockUsers = () => {
  if (!config.useMockData) {
    // In production with real DB, this would query the database
    console.warn('Mock data disabled. Ensure database is configured.');
    return [];
  }

  try {
    return config.mockUsers;
  } catch (error) {
    console.error('Error parsing mock users:', error);
    return [];
  }
};

// ============ ROUTES ============

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      version: config.appVersion,
      environment: config.nodeEnv,
    });
  } catch (error) {
    res.status(500).json({ error: config.errorMessages.serverError });
  }
});

// Secure /users endpoint with full configuration support
app.get('/users',
  authenticateToken,
  query('limit')
    .optional()
    .isInt({ min: config.queryMinLimit, max: config.queryMaxLimit })
    .toInt(),
  (req, res, next) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: config.errorMessages.invalidInput,
          details: errors.array()
        });
      }

      const limit = req.query.limit || config.queryMaxLimit;
      const users = getMockUsers().slice(0, limit);

      res.json(users);
    } catch (error) {
      next(error);
    }
  }
);

// Health check endpoint (no auth required)
app.get('/config/health', (req, res) => {
  res.json({
    appVersion: config.appVersion,
    environment: config.nodeEnv,
    timestamp: new Date().toISOString(),
  });
});

// ============ ERROR HANDLING ============

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: config.errorMessages.notFound,
    path: req.path,
  });
});

// Error handling middleware (must be last)
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error:`, err.message);

  const isDevelopment = config.nodeEnv === 'development';

  res.status(err.status || 500).json({
    error: config.errorMessages.serverError,
    ...(isDevelopment && { 
      message: err.message,
      stack: err.stack
    }),
  });
});

// ============ SERVER STARTUP ============

const server = app.listen(config.port, config.host, () => {
  console.log(`\n${'='.repeat(60)}`);
  console.log(`[${new Date().toISOString()}] Server started successfully`);
  console.log(`Address: http://${config.host}:${config.port}`);
  console.log(`Environment: ${config.nodeEnv}`);
  console.log(`Version: ${config.appVersion}`);
  console.log(`${'='.repeat(60)}\n`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log(`[${new Date().toISOString()}] SIGTERM received, shutting down gracefully...`);
  server.close(() => {
    console.log(`[${new Date().toISOString()}] Server closed`);
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error(`[${new Date().toISOString()}] Uncaught Exception:`, err);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error(`[${new Date().toISOString()}] Unhandled Rejection at:`, promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

# Configuration Validation and Best Practices

## Configuration Validation Strategy

### 1. Startup Validation

Ensure all required configurations are present and valid before starting the server:

```javascript
const validateConfig = () => {
  const errors = [];

  // Validate required production config
  if (process.env.NODE_ENV === 'production') {
    if (!process.env.API_TOKEN) {
      errors.push('API_TOKEN is required in production');
    }
    if (!process.env.ALLOWED_ORIGINS) {
      errors.push('ALLOWED_ORIGINS is required in production');
    }
  }

  // Validate port is valid
  const port = parseInt(process.env.PORT || 3000);
  if (isNaN(port) || port < 1 || port > 65535) {
    errors.push(`Invalid PORT: ${port} (must be 1-65535)`);
  }

  // Validate rate limit values
  const rateLimitMax = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || 100);
  if (isNaN(rateLimitMax) || rateLimitMax < 1) {
    errors.push(`Invalid RATE_LIMIT_MAX_REQUESTS: ${rateLimitMax}`);
  }

  if (errors.length > 0) {
    console.error('Configuration Validation Errors:');
    errors.forEach(err => console.error(`  - ${err}`));
    process.exit(1);
  }
};

// Call before starting server
validateConfig();
```

### 2. Using Joi/Yup for Schema Validation

```javascript
const joi = require('joi');

const configSchema = joi.object({
  PORT: joi.number().port().default(3000),
  HOST: joi.string().ip().default('0.0.0.0'),
  NODE_ENV: joi.string()
    .valid('development', 'staging', 'production')
    .default('development'),
  API_TOKEN: joi.string()
    .required()
    .when('NODE_ENV', {
      is: 'production',
      then: joi.required(),
      otherwise: joi.optional()
    }),
  RATE_LIMIT_MAX_REQUESTS: joi.number().min(1).default(100),
  QUERY_MAX_LIMIT: joi.number().min(1).max(10000).default(100),
  ALLOWED_ORIGINS: joi.string().default('http://localhost:3000'),
}).unknown(true);

const validateEnvironment = () => {
  const { error, value } = configSchema.validate(process.env, { 
    abortEarly: false 
  });

  if (error) {
    console.error('Configuration Validation Failed:');
    error.details.forEach(detail => {
      console.error(`  ${detail.path.join('.')}: ${detail.message}`);
    });
    process.exit(1);
  }

  return value;
};
```

### 3. Using Convict for Advanced Configuration

```javascript
const convict = require('convict');

const config = convict({
  port: {
    doc: 'The port to bind.',
    format: 'port',
    default: 3000,
    env: 'PORT'
  },
  host: {
    doc: 'The host to bind to.',
    format: 'ipaddress',
    default: '0.0.0.0',
    env: 'HOST'
  },
  nodeEnv: {
    doc: 'The application environment.',
    format: ['development', 'staging', 'production'],
    default: 'development',
    env: 'NODE_ENV'
  },
  api: {
    token: {
      doc: 'API authentication token',
      format: String,
      default: 'change-me',
      env: 'API_TOKEN',
      sensitive: true
    }
  },
  rateLimit: {
    windowMs: {
      doc: 'Rate limit window in milliseconds',
      format: 'nat',
      default: 900000,
      env: 'RATE_LIMIT_WINDOW_MS'
    },
    maxRequests: {
      doc: 'Max requests per window',
      format: 'nat',
      default: 100,
      env: 'RATE_LIMIT_MAX_REQUESTS'
    }
  }
});

// Load environment
config.load(process.env);

// Validate
config.validate({ allowed: 'strict' });

module.exports = config;
```

---

## Configuration Loading Order

For robust configuration management, follow this order:

```
1. Defaults (in code)
   ↓
2. Environment variables
   ↓
3. .env file (if exists)
   ↓
4. Configuration file (config.json)
   ↓
5. Command-line arguments
   ↓
6. Validation & Error Handling
```

---

## Recommended Setup

### app.js
```javascript
require('dotenv').config({ path: process.env.ENV_FILE || '.env' });

const config = require('./config');
// ... rest of app
```

### config/index.js
```javascript
module.exports = {
  // Server
  port: process.env.PORT || 3000,
  host: process.env.HOST || '0.0.0.0',
  nodeEnv: process.env.NODE_ENV || 'development',

  // Security
  apiToken: process.env.API_TOKEN || 'default-token',

  // ... other config
};
```

### config/validation.js
```javascript
const config = require('./index');

const validate = () => {
  if (config.nodeEnv === 'production') {
    if (!process.env.API_TOKEN) {
      throw new Error('API_TOKEN must be set in production');
    }
  }
};

validate();
module.exports = config;
```

---

## Different Configurations Per Environment

### Option 1: Separate .env files

```bash
# Files
.env.development
.env.staging
.env.production
.env.local (gitignored)

# Usage
NODE_ENV=production ENV_FILE=.env.production npm start
```

### Option 2: Using 'config' npm package

Directory structure:
```
config/
  default.json
  development.json
  production.json
  staging.json
```

Usage:
```javascript
const config = require('config');
const port = config.get('port');
```

### Option 3: AWS Systems Manager Parameter Store

```javascript
const AWS = require('aws-sdk');
const ssm = new AWS.Systems Manager();

async function loadConfig() {
  const params = await ssm.getParameters({
    Names: ['/myapp/port', '/myapp/api-token'],
    WithDecryption: true
  }).promise();

  return params.Parameters.reduce((acc, param) => {
    const key = param.Name.split('/').pop();
    acc[key] = param.Value;
    return acc;
  }, {});
}
```

---

## Checklist: Configuration Validation

- [ ] All required variables are checked on startup
- [ ] Types are validated (strings, numbers, booleans)
- [ ] Ranges are validated (port 1-65535, limits > 0)
- [ ] Production config requires explicit values (no defaults)
- [ ] Sensitive values marked as non-loggable
- [ ] Clear error messages on validation failure
- [ ] Startup fails if critical config is missing
- [ ] Configuration is logged (without secrets) on startup
- [ ] Different environments use different default values
- [ ] Configuration can be overridden by environment variables

---

## Security: Keeping Secrets Safe

### ✓ Good Practices
```javascript
// Load from secure vault
const secret = await vault.getSecret('app/api-token');

// Use temporary credentials
const tempCreds = await assumeRole();

// Rotate regularly
// Check credential age and warn if old
```

### ✗ Bad Practices
```javascript
// Hardcoded secrets
const apiToken = 'sk_live_abc123';

// Secrets in .env committed to git
DATABASE_URL=postgres://user:password@host/db

// Logging secrets
console.log('Using token:', config.apiToken);

// Storing in comments
// apiToken = 'old-token-abc123'
```

---

## Example: Complete Configuration Setup

```javascript
// config.js
require('dotenv').config();

class Config {
  constructor() {
    this.validate();
  }

  validate() {
    const required = this.getRequiredVars();
    const missing = required.filter(v => !process.env[v]);

    if (missing.length > 0) {
      throw new Error(
        `Missing required environment variables: ${missing.join(', ')}\n` +
        `Please see .env.example for configuration template`
      );
    }
  }

  getRequiredVars() {
    if (process.env.NODE_ENV === 'production') {
      return ['API_TOKEN', 'ALLOWED_ORIGINS', 'DATABASE_URL'];
    }
    return [];
  }

  get port() {
    const port = parseInt(process.env.PORT || 3000);
    if (isNaN(port) || port < 1 || port > 65535) {
      throw new Error(`Invalid PORT: ${port}`);
    }
    return port;
  }

  get isDevelopment() {
    return this.nodeEnv === 'development';
  }

  get isProduction() {
    return this.nodeEnv === 'production';
  }

  get nodeEnv() {
    return process.env.NODE_ENV || 'development';
  }

  get apiToken() {
    return process.env.API_TOKEN || 'dev-token';
  }

  get allowedOrigins() {
    return (process.env.ALLOWED_ORIGINS || 'http://localhost:3000')
      .split(',')
      .map(o => o.trim());
  }

  toJSON() {
    // Never include secrets in JSON output
    return {
      port: this.port,
      nodeEnv: this.nodeEnv,
      isDevelopment: this.isDevelopment,
      isProduction: this.isProduction,
      allowedOrigins: this.allowedOrigins,
    };
  }
}

module.exports = new Config();
```

---

