// Secure application with environment variables and best practices
// Load environment variables early
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Configuration from environment variables
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const API_KEY = process.env.API_KEY; // Required in production

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parser middleware
app.use(express.json({ limit: '10kb' }));

// Health check endpoint (no sensitive data)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

// Protected users endpoint with authentication
app.get('/users', authenticateRequest, (req, res) => {
  // Return minimal data without sensitive fields
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];

  res.json(users);
});

// Authentication middleware
function authenticateRequest(req, res, next) {
  const apiKey = req.headers['x-api-key'];

  if (NODE_ENV === 'production' && !apiKey) {
    return res.status(401).json({ error: 'Missing API key' });
  }

  if (NODE_ENV === 'production' && apiKey !== API_KEY) {
    return res.status(403).json({ error: 'Invalid API key' });
  }

  next();
}

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err);

  // Don't expose stack traces in production
  const message = NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(500).json({ error: message });
});

// Start server
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`[${NODE_ENV}] Server running on port ${PORT}`);
  });
}

module.exports = app;

