require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// ============================================================================
// CONFIGURATION FROM ENVIRONMENT VARIABLES
// ============================================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
const RATE_LIMIT_ENABLED = process.env.RATE_LIMIT_ENABLED !== 'false';
const RATE_LIMIT_WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10);
const RATE_LIMIT_MAX = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100', 10);
const LOG_FORMAT = process.env.LOG_FORMAT || 'combined';

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Set security HTTP headers
app.use(helmet());

// Enable CORS
app.use(cors({
  origin: ALLOWED_ORIGINS.map(origin => origin.trim()),
  credentials: process.env.CORS_CREDENTIALS === 'true',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting
if (RATE_LIMIT_ENABLED) {
  const limiter = rateLimit({
    windowMs: RATE_LIMIT_WINDOW_MS,
    max: RATE_LIMIT_MAX,
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
  });

  app.use(limiter);
}

// ============================================================================
// LOGGING MIDDLEWARE
// ============================================================================

app.use(morgan(LOG_FORMAT));

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

/**
 * Get users endpoint
 * GET /users
 * NOTE: In production, this should require authentication and fetch from database
 */
app.get('/users', (req, res) => {
  // In test mode, load from environment variable
  if (NODE_ENV === 'test' && process.env.TEST_USERS) {
    try {
      const users = JSON.parse(process.env.TEST_USERS);
      return res.json(users);
    } catch (err) {
      console.error('Failed to parse TEST_USERS from environment:', err);
    }
  }

  // Default response (should be replaced with database query in production)
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' }
  ]);
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  console.error('[Error]', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method
  });

  const statusCode = err.statusCode || err.status || 500;

  // Never expose stack traces in production
  const response = {
    error: err.message || 'Internal server error',
    ...(NODE_ENV === 'development' && { stack: err.stack })
  };

  res.status(statusCode).json(response);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, HOST, () => {
  console.log(`
╔════════════════════════════════════════════════════════════╗
║                  Server Started Successfully              ║
╠════════════════════════════════════════════════════════════╣
║ Environment:    ${NODE_ENV.padEnd(43)}║
║ Listen Address: ${`http://${HOST}:${PORT}`.padEnd(43)}║
║ CORS Enabled:   ${ALLOWED_ORIGINS.join(', ').substring(0, 45).padEnd(43)}║
║ Rate Limiting:  ${(RATE_LIMIT_ENABLED ? 'Enabled' : 'Disabled').padEnd(43)}║
╚════════════════════════════════════════════════════════════╝
  `);
});

// ============================================================================
// GRACEFUL SHUTDOWN
// ============================================================================

const gracefulShutdown = (signal) => {
  console.log(`\n[${signal}] Received, starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
