/**
 * Configuration management - loads and validates environment variables
 * Never log or expose sensitive configuration
 */

require('dotenv').config();

const config = {
  // Server
  port: parseInt(process.env.PORT || '3000', 10),
  host: process.env.HOST || 'localhost',
  nodeEnv: process.env.NODE_ENV || 'development',

  // Security
  allowedOrigins: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),

  // Database
  databaseUrl: process.env.DATABASE_URL,

  // API Keys (never log these)
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    region: process.env.AWS_REGION || 'us-east-1',
  },

  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN,

  // Logging
  logLevel: process.env.LOG_LEVEL || 'info',
};

// Validate required configuration
function validateConfig() {
  if (config.nodeEnv === 'production') {
    const requiredInProduction = [
      'databaseUrl',
      'anthropicApiKey',
      'stripeSecretKey',
    ];

    const missing = requiredInProduction.filter(key => !config[key]);
    if (missing.length > 0) {
      throw new Error(`Missing required environment variables for production: ${missing.join(', ')}`);
    }
  }
}

// Safe logging function - never logs sensitive data
function logConfig() {
  console.log('Configuration loaded:', {
    port: config.port,
    host: config.host,
    nodeEnv: config.nodeEnv,
    allowedOrigins: config.allowedOrigins,
    logLevel: config.logLevel,
    // Intentionally NOT logging any API keys or credentials
  });
}

validateConfig();

module.exports = {
  config,
  logConfig,
};

