const RATE_LIMIT_WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 15 * 60 * 1000;
const RATE_LIMIT_MAX_REQUESTS = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100;

// Payload limits
const MAX_JSON_SIZE = process.env.MAX_JSON_SIZE || '10kb';

// ==================== SECURITY MIDDLEWARE ====================

// Add security headers
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: RATE_LIMIT_MAX_REQUESTS,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Parse JSON with configurable size limits to prevent payload attacks
app.use(express.json({ limit: MAX_JSON_SIZE }));

// ==================== LOGGING ====================

// Simple logger function
const log = (level, message, data = {}) => {
  if (NODE_ENV === 'production') {
    // In production, use JSON logging for structured logs
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      level,
      message,
      ...data
    }));
  } else {
    // In development, use readable format
    console.log(`[${level}] ${message}`, data);
  }
};

// ==================== ROUTES ====================

// Health check endpoint (public, for monitoring/load balancing)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// Protected users endpoint (example with basic auth check)
app.get('/users', (req, res) => {
  // TODO: Add proper authentication (JWT, OAuth, etc.)
  // This is just an example - implement proper auth for production
  const authHeader = req.headers.authorization;
  if (!authHeader) {
    log('warn', 'Unauthorized access attempt to /users endpoint', {
      ip: req.ip,
      timestamp: new Date().toISOString()
    });
    return res.status(401).json({ error: 'Unauthorized' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ==================== ERROR HANDLING ====================

// 404 Not Found middleware
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method,
  });
});

// Error handling middleware (must be last)
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = err.message || 'Internal Server Error';

  log('error', message, {
    status,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Don't expose error details in production
  res.status(status).json({
    error: NODE_ENV === 'production'
      ? 'Internal Server Error'
      : message,
    requestId: req.id, // Can be set by request ID middleware if available
  });
});

// ==================== SERVER START ====================

const server = app.listen(PORT, HOST, () => {
  log('info', `Server running`, {
    port: PORT,
    host: HOST,
    environment: NODE_ENV,
    nodeVersion: process.version,
    uptime: process.uptime(),
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  log('info', 'SIGTERM signal received: closing HTTP server');
  server.close(() => {
    log('info', 'HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  log('info', 'SIGINT signal received: closing HTTP server');
  server.close(() => {
    log('info', 'HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

