 * Run this at application startup
 */

const chalk = require('chalk'); // Optional: for colored output

/**
 * Environment variable schema
 */
const CONFIG_SCHEMA = {
  required: [
    'NODE_ENV',
  ],
  optional: [
    {
      name: 'PORT',
      default: 3000,
      type: 'number',
      description: 'Server port'
    },
    {
      name: 'HOST',
      default: '0.0.0.0',
      type: 'string',
      description: 'Server host'
    },
    {
      name: 'LOG_LEVEL',
      default: 'info',
      type: 'string',
      description: 'Logging level (debug, info, warn, error)',
      validate: (value) => ['debug', 'info', 'warn', 'error'].includes(value)
    },
    {
      name: 'RATE_LIMIT_WINDOW_MS',
      default: 900000,
      type: 'number',
      description: 'Rate limit window in milliseconds'
    },
    {
      name: 'RATE_LIMIT_MAX_REQUESTS',
      default: 100,
      type: 'number',
      description: 'Max requests per rate limit window'
    },
    {
      name: 'MAX_JSON_SIZE',
      default: '10kb',
      type: 'string',
      description: 'Max JSON payload size'
    },
  ]
};

/**
 * Validate and load configuration
 * @returns {Object} Validated configuration object
 * @throws {Error} If required variables are missing or invalid
 */
function validateConfig() {
  const config = {};
  const errors = [];
  const warnings = [];

  console.log('\n📋 Validating Environment Configuration...\n');

  // Check required variables
  for (const varName of CONFIG_SCHEMA.required) {
    if (!process.env[varName]) {
      errors.push(`❌ Missing required environment variable: ${varName}`);
    } else {
      config[varName] = process.env[varName];
      console.log(`✅ ${varName} = ${process.env[varName]}`);
    }
  }

  // Check optional variables
  for (const varSchema of CONFIG_SCHEMA.optional) {
    const { name, default: defaultValue, type, description, validate } = varSchema;
    const value = process.env[name];

    if (!value) {
      config[name] = defaultValue;
      console.log(`⚠️  ${name} not set, using default: ${defaultValue} (${description})`);
      warnings.push(`${name} using default value`);
    } else {
      // Type validation
      if (type === 'number') {
        const numValue = parseInt(value, 10);
        if (isNaN(numValue)) {
          errors.push(`❌ ${name} must be a number, got: ${value}`);
        } else {
          config[name] = numValue;
          console.log(`✅ ${name} = ${numValue}`);
        }
      } else {
        config[name] = value;
        console.log(`✅ ${name} = ${value}`);
      }

      // Custom validation
      if (validate && !validate(value)) {
        errors.push(`❌ ${name} has invalid value: ${value}`);
      }
    }
  }

  console.log('\n' + '='.repeat(50) + '\n');

  // Report errors
  if (errors.length > 0) {
    console.error('❌ Configuration Validation FAILED:\n');
    errors.forEach(error => console.error(error));
    console.error('\nPlease fix the above errors and restart the application.\n');
    process.exit(1);
  }

  // Report warnings
  if (warnings.length > 0) {
    console.warn('⚠️  Configuration Warnings:\n');
    warnings.forEach(warning => console.warn(`  • ${warning}`));
    console.warn('\nIf this is production, consider setting these variables.\n');
  }

  console.log('✅ Configuration Validation PASSED\n');
  return config;
}

/**
 * Print configuration summary
 */
function printConfigSummary(config) {
  console.log('📊 Configuration Summary:');
  console.log('========================\n');

  for (const [key, value] of Object.entries(config)) {
    if (key.includes('SECRET') || key.includes('KEY') || key.includes('PASSWORD')) {
      console.log(`${key}: ***REDACTED***`);
    } else {
      console.log(`${key}: ${value}`);
    }
  }

  console.log('\n');
}

module.exports = {
  validateConfig,
  printConfigSummary,
  CONFIG_SCHEMA
};

