// Secure application with environment variable configuration
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

// Load environment variables from .env file (for development only)
require('dotenv').config();

const app = express();

// ============================================
// ENVIRONMENT VARIABLES (with defaults where appropriate)
// ============================================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const LOG_LEVEL = process.env.LOG_LEVEL || 'info';

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '15') * 60 * 1000,
  max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100'),
  message: 'Too many requests, please try again later.'
});
app.use(limiter);

// ============================================
// ROUTES
// ============================================
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ============================================
// ERROR HANDLING
// ============================================
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(status).json({ error: message });
});

// ============================================
// SERVER STARTUP
// ============================================
const server = app.listen(PORT, () => {
  console.log(`[${NODE_ENV}] Server running on port ${PORT}`);
  if (NODE_ENV !== 'production') {
    console.log(`Log level: ${LOG_LEVEL}`);
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

