/**
 * Validates that all required environment variables are set
 * Throws error if any required variables are missing in production
 */
const validateConfig = () => {
  // Variables that are ALWAYS required (all environments)
  const alwaysRequired = [];

  // Variables required only in production
  const productionRequired = [
    'SESSION_SECRET',
    'JWT_SECRET',
    'DATABASE_URL',
  ];

  // Variables required only in test
  const testRequired = [];

  const getRequired = () => {
    let required = [...alwaysRequired];

    if (config.isProduction) {
      required = [...required, ...productionRequired];
    }
    if (config.isTest) {
      required = [...required, ...testRequired];
    }

    return required;
  };

  const required = getRequired();
  const missing = required.filter(envVar => !process.env[envVar]);

  if (missing.length > 0) {
    const message = 
      `Missing required environment variables in ${config.nodeEnv} mode:\n` +
      `  ${missing.join('\n  ')}\n\n` +
      `Please set these variables in your .env file or system environment.`;

    throw new Error(message);
