      return res.status(400).json({
        error: 'Invalid query parameters',
        invalid: invalidParams,
        allowed: allowedParams,
      });
    }

    // Validate pagination limits
    const limit = Math.min(parseInt(req.query.limit, 10) || 10, 100);
    const offset = Math.max(parseInt(req.query.offset, 10) || 0, 0);

    if (limit < 1 || offset < 0) {
      return res.status(400).json({
        error: 'Invalid pagination parameters',
      });
    }

    // Return users (without sensitive data like emails in this case)
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    res.status(200).json({
      data: users.slice(offset, offset + limit),
      pagination: {
        limit,
        offset,
        total: users.length,
      },
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: config.isDevelopment 
        ? error.message 
        : 'Internal server error',
    });
  }
});

// ============================================================
// 404 Handler
// ============================================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method,
  });
});

// ============================================================
// Error Handling Middleware
// ============================================================

app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose sensitive error details in production
  const response = {
    error: config.isProduction 
      ? 'Internal Server Error' 
      : err.message,
  };

  // Include stack trace only in development
  if (config.isDevelopment) {
    response.stack = err.stack;
  }

  res.status(err.status || 500).json(response);
});

// ============================================================
// Server Startup
// ============================================================

const server = app.listen(config.port, config.host, () => {
  console.log(`
╔════════════════════════════════════════╗
║     Server Started Successfully        ║
╠════════════════════════════════════════╣
║ Host:         ${config.host.padEnd(25)} ║
║ Port:         ${String(config.port).padEnd(25)} ║
║ Environment:  ${config.nodeEnv.padEnd(25)} ║
║ Debug Mode:   ${String(config.features.enableDebugMode).padEnd(25)} ║
╚════════════════════════════════════════╝
  `);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

