    // Only include email if explicitly enabled via environment variable
    if (config.enableUserEmails && email) {
      response.email = email;
    }

    return response;
  });

  res.json(users);
});

/**
 * 404 handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

app.listen(config.port, config.host, () => {
