// Secure version of the application with security best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

// ============================================
// Security Middleware
// ============================================

// 1. Security Headers
app.use(helmet());

// 2. CORS Configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST'],
  optionsSuccessStatus: 200,
  maxAge: 3600
}));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => process.env.NODE_ENV === 'development' // Skip in development
});

app.use(limiter);

// 4. Request Body Parsing
app.use(express.json({ limit: '10kb' })); // Prevent large payloads
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ============================================
// Request Logging Middleware
// ============================================

app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} - ${res.statusCode} (${duration}ms)`);
  });
  next();
});

// ============================================
// Routes
// ============================================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

app.get('/users',
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    // Validate request
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = Math.min(req.query.limit || 10, 100);

    // In production, this would query a database with proper:
    // - Connection pooling
    // - Parameterized queries
    // - Access controls
    // - Data filtering
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ].slice(0, limit);

    res.json(users);
  }
);

// ============================================
// 404 Handler
// ============================================

app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// ============================================
// Error Handler (Must be last!)
// ============================================

app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  const status = err.status || err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Don't expose stack traces in production
  const message = isDevelopment ? err.message : 'Internal Server Error';
  const stack = isDevelopment ? err.stack : undefined;

  res.status(status).json({
    error: {
      message,
      ...(stack && { stack })
    }
  });
});

// ============================================
// Server Startup
// ============================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`🔒 Secure server running on port ${PORT} in ${NODE_ENV} mode`);
    if (NODE_ENV === 'development') {
      console.log('⚠️  Running in development mode - debug info exposed');
    }
  });
}

module.exports = app;

