// Production-ready application with environment variables properly configured
// Removes all hardcoded values for flexibility and deployability

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

// ============================================
// Configuration from Environment Variables
// ============================================

// Server Configuration
const PORT = parseInt(process.env.PORT, 10) || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const HOST = process.env.HOST || '0.0.0.0';

// Feature Flags
const DEBUG = process.env.DEBUG === 'true';
const MOCK_MODE = process.env.MOCK_MODE !== 'false'; // Default true for dev

// CORS Configuration
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000')
  .split(',')
  .map(origin => origin.trim());

// Rate Limiting Configuration
const RATE_LIMIT_WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 15 * 60 * 1000;
const RATE_LIMIT_MAX_REQUESTS = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100;

// Payload Size Limits
const PAYLOAD_LIMIT = process.env.PAYLOAD_LIMIT || '10kb';

// Logging Configuration
const LOG_LEVEL = process.env.LOG_LEVEL || 'info';

// Mock Data (configurable for testing)
const MOCK_USERS = process.env.MOCK_USERS 
  ? (() => {
      try {
        return JSON.parse(process.env.MOCK_USERS);
      } catch (e) {
        console.error('Failed to parse MOCK_USERS:', e.message);
        return [];
      }
    })()
  : [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

// ============================================
// Configuration Validation
// ============================================

function validateConfiguration() {
  const errors = [];

  // Validate PORT
  if (PORT < 1 || PORT > 65535) {
    errors.push(`Invalid PORT: ${PORT} (must be 1-65535)`);
  }

  // Validate NODE_ENV
  if (!['development', 'staging', 'production'].includes(NODE_ENV)) {
    errors.push(`Invalid NODE_ENV: ${NODE_ENV} (must be development, staging, or production)`);
  }

  // Validate LOG_LEVEL
  if (!['debug', 'info', 'warn', 'error'].includes(LOG_LEVEL)) {
    errors.push(`Invalid LOG_LEVEL: ${LOG_LEVEL} (must be debug, info, warn, or error)`);
  }

  // Validate ALLOWED_ORIGINS
  if (!ALLOWED_ORIGINS || ALLOWED_ORIGINS.length === 0) {
    errors.push('ALLOWED_ORIGINS is required');
  }

  if (errors.length > 0) {
    console.error('Configuration Validation Errors:');
    errors.forEach(error => console.error(`  - ${error}`));
    process.exit(1);
  }
}

// ============================================
// Initialize Express App
// ============================================

const app = express();

// ============================================
// Security Middleware
// ============================================

// Security Headers
app.use(helmet());

// CORS Configuration
app.use(cors({
  origin: ALLOWED_ORIGINS,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  optionsSuccessStatus: 200,
  maxAge: 3600
}));

// Rate Limiting
const limiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: RATE_LIMIT_MAX_REQUESTS,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => NODE_ENV === 'development' && DEBUG
});

app.use(limiter);

// Body Parser with Size Limits
app.use(express.json({ limit: PAYLOAD_LIMIT }));
app.use(express.urlencoded({ extended: false, limit: PAYLOAD_LIMIT }));

// ============================================
// Logging Middleware
// ============================================

app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;

    // Log format: LEVEL | METHOD PATH STATUS DURATION
    const logEntry = {
      level: 'info',
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      timestamp: new Date().toISOString(),
      ...(DEBUG && { ip: req.ip, userAgent: req.get('user-agent') })
    };

    // Only log based on configured level
    if (NODE_ENV === 'production') {
      if (res.statusCode >= 500) {
        console.error(JSON.stringify(logEntry));
      } else if (LOG_LEVEL === 'info' || LOG_LEVEL === 'debug') {
        console.log(JSON.stringify(logEntry));
      }
    } else {
      // Development: always log
      console.log(`[${logEntry.level.toUpperCase()}] ${logEntry.method} ${logEntry.path} - ${logEntry.status} (${logEntry.duration})`);
    }
  });

  next();
});

// ============================================
// Routes
// ============================================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    uptime: process.uptime(),
    ...(DEBUG && { memoryUsage: process.memoryUsage() })
  });
});

app.get('/config',
  // Only allow in development
  (req, res, next) => {
    if (NODE_ENV !== 'development') {
      return res.status(403).json({ error: 'Not available in this environment' });
    }
    next();
  },
  (req, res) => {
    // Return non-sensitive configuration info
    res.json({
      port: PORT,
      host: HOST,
      environment: NODE_ENV,
      debug: DEBUG,
      mockMode: MOCK_MODE,
      corsOrigins: ALLOWED_ORIGINS,
      rateLimiting: {
        windowMs: RATE_LIMIT_WINDOW_MS,
        maxRequests: RATE_LIMIT_MAX_REQUESTS
      }
    });
  }
);

app.get('/users',
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .toInt(),
  (req, res) => {
    // Validate
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    if (MOCK_MODE) {
      // Return mock data
      const users = MOCK_USERS.slice(offset, offset + limit);
      return res.json({
        data: users,
        total: MOCK_USERS.length,
        limit,
        offset,
        mock: true
      });
    }

    // In production with mock disabled, would query database
    return res.status(501).json({
      error: 'Database not configured',
      message: 'Set MOCK_MODE=true or configure DATABASE_URL'
    });
  }
);

// ============================================
// 404 Handler
// ============================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// ============================================
// Error Handler (Must be last!)
// ============================================

app.use((err, req, res, next) => {
  const isDevelopment = NODE_ENV === 'development';

  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    isDevelopment
  });

  const status = err.status || err.statusCode || 500;

  // Build response
  const response = {
    error: {
      message: isDevelopment 
        ? err.message 
        : 'Internal Server Error'
    }
  };

  // Add stack trace only in development
  if (isDevelopment && err.stack) {
    response.error.stack = err.stack;
  }

  // Add request info in development
  if (isDevelopment && DEBUG) {
    response.request = {
      method: req.method,
      path: req.path,
      query: req.query
    };
  }

  res.status(status).json(response);
});

// ============================================
// Server Startup
// ============================================

function startServer() {
  // Validate configuration on startup
  validateConfiguration();

  app.listen(PORT, HOST, () => {
    const startupInfo = {
      message: 'Server started',
      port: PORT,
      host: HOST,
      environment: NODE_ENV,
      timestamp: new Date().toISOString(),
      pid: process.pid,
      nodeVersion: process.version
    };

    console.log(JSON.stringify(startupInfo));

    if (NODE_ENV === 'development') {
      console.log('\n📋 Configuration:');
      console.log(`   Port: ${PORT}`);
      console.log(`   Environment: ${NODE_ENV}`);
      console.log(`   Debug: ${DEBUG}`);
      console.log(`   Mock Mode: ${MOCK_MODE}`);
      console.log(`   Log Level: ${LOG_LEVEL}`);
      console.log(`   Allowed Origins: ${ALLOWED_ORIGINS.join(', ')}`);
      console.log(`   Rate Limit: ${RATE_LIMIT_MAX_REQUESTS} requests per ${RATE_LIMIT_WINDOW_MS / 1000}s`);
      console.log('\n🔗 Available Endpoints:');
      console.log(`   GET  http://${HOST}:${PORT}/health`);
      console.log(`   GET  http://${HOST}:${PORT}/config (dev only)`);
      console.log(`   GET  http://${HOST}:${PORT}/users`);
      console.log('');
    }
  });
}

// Start server if this is the main module
if (require.main === module) {
  startServer();
}

module.exports = app;

